cw_demod(int16_t *src, int16_t *dst, size_t len)
{
  weaver_demod_conf_t dc = {
    mode_freqoffset_phasestep, cw_tone_phasestep, &bq_cw_i, &bq_cw_q
  };

  demod_weaver(src, dst, len, &dc);
}

